-- DarkChaos: rogue poisons, healthstone and soulstone for levels 81-255 (generated by tools/balance/gen_class_items.py)
--
-- Poisons: Instant, Deadly, Wound and Anesthetic Poison get one rank per band (usable from levels 81, 100, 130, 160).
-- Each is a new item (423101-423134) coating the weapon with a new enchantment (922101-922134) whose poison
-- (920201-920234) hits like the level-80 one grown with weapon damage. Every vendor of the level-80 poison
-- sells them. Crippling and Mind-numbing Poison are percentages and keep their stock ranks.
-- Create Healthstone rank 9 (level 81) makes a Dread Healthstone: 20% of maximum health, 22% / 24% with
-- Improved Healthstone. Create Soulstone rank 8 makes a Dread Soulstone: resurrection with 20% of
-- maximum health and mana. Both need the worldserver build that knows them (spell_warlock.cpp, Player.cpp).
--
-- The spells, items and enchantments are rows of Spell.dbc, Item.dbc and SpellItemEnchantment.dbc,
-- which ship with this file. Re-running gives the same result. Apply to acore_world, then restart.

DROP TEMPORARY TABLE IF EXISTS `dc_tmp_class_item`;
CREATE TEMPORARY TABLE `dc_tmp_class_item` SELECT * FROM `item_template` WHERE `entry` = 43231;
UPDATE `dc_tmp_class_item` SET `entry` = 423101, `name` = 'Instant Poison X', `RequiredLevel` = 81, `ItemLevel` = 81, `spellid_1` = 920101, `BuyPrice` = `BuyPrice` * 1.0479, `SellPrice` = `SellPrice` * 1.0479, `VerifiedBuild` = 0;
REPLACE INTO `item_template` SELECT * FROM `dc_tmp_class_item`;
