DROP TEMPORARY TABLE IF EXISTS `dc_tmp_class_item_map`;
CREATE TEMPORARY TABLE `dc_tmp_class_item_map` (`new_id` INT NOT NULL PRIMARY KEY, `old_id` INT NOT NULL, `step` TINYINT UNSIGNED NOT NULL) ENGINE=InnoDB;
DELETE FROM `dc_tmp_class_item_map`;
INSERT INTO `dc_tmp_class_item_map` (`new_id`, `old_id`, `step`) VALUES (920101, 57968, 1), (920201, 57965, 1), (920102, 57968, 2), (920202, 57965, 2), (920103, 57968, 3), (920203, 57965, 3), (920104, 57968, 4), (920204, 57965, 4), (920111, 57973, 1), (920211, 57970, 1), (920112, 57973, 2), (920212, 57970, 2), (920113, 57973, 3), (920213, 57970, 3), (920114, 57973, 4), (920214, 57970, 4), (920121, 57978, 1), (920221, 57975, 1), (920122, 57978, 2), (920222, 57975, 2), (920123, 57978, 3), (920223, 57975, 3), (920124, 57978, 4), (920224, 57975, 4), (920131, 57982, 1), (920231, 57981, 1), (920132, 57982, 2), (920232, 57981, 2), (920133, 57982, 3), (920233, 57981, 3), (920134, 57982, 4), (920234, 57981, 4), (920009, 47878, 1), (920010, 47884, 1);

-- Rank chains (Deadly Poison's script, spell_rog_deadly_poison, is registered on its chain)
DELETE FROM `spell_ranks` WHERE `spell_id` IN (920006, 920007, 920008, 920009, 920010, 920011, 920012, 920101, 920102, 920103, 920104, 920111, 920112, 920113, 920114, 920121, 920122, 920123, 920124, 920131, 920132, 920133, 920134, 920201, 920202, 920203, 920204, 920211, 920212, 920213, 920214, 920221, 920222, 920223, 920224, 920231, 920232, 920233, 920234);
INSERT INTO `spell_ranks` (`first_spell_id`, `spell_id`, `rank`) SELECT `r`.`first_spell_id`, `m`.`new_id`, `r`.`rank` + `m`.`step` FROM `dc_tmp_class_item_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`old_id`;

-- Attack power coefficients of the poisons: by the spell's own id, else by its first rank's
DELETE FROM `spell_bonus_data` WHERE `entry` IN (920006, 920007, 920008, 920009, 920010, 920011, 920012, 920101, 920102, 920103, 920104, 920111, 920112, 920113, 920114, 920121, 920122, 920123, 920124, 920131, 920132, 920133, 920134, 920201, 920202, 920203, 920204, 920211, 920212, 920213, 920214, 920221, 920222, 920223, 920224, 920231, 920232, 920233, 920234);
INSERT INTO `spell_bonus_data` (`entry`, `direct_bonus`, `dot_bonus`, `ap_bonus`, `ap_dot_bonus`, `comments`) SELECT `m`.`new_id`, `b`.`direct_bonus`, `b`.`dot_bonus`, `b`.`ap_bonus`, `b`.`ap_dot_bonus`, `b`.`comments` FROM `dc_tmp_class_item_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`old_id` JOIN `spell_bonus_data` AS `b` ON `b`.`entry` = CASE WHEN EXISTS (SELECT 1 FROM `spell_bonus_data` AS `o` WHERE `o`.`entry` = `m`.`old_id`) THEN `m`.`old_id` ELSE `r`.`first_spell_id` END;

-- Trainer offers of the two create spells (every trainer of the old rank, at level 81)
DELETE FROM `trainer_spell` WHERE `SpellId` IN (920009, 920010);
INSERT INTO `trainer_spell` (`TrainerId`, `SpellId`, `MoneyCost`, `ReqSkillLine`, `ReqSkillRank`, `ReqAbility1`, `ReqAbility2`, `ReqAbility3`, `ReqLevel`, `VerifiedBuild`) SELECT `t`.`TrainerId`, `m`.`new_id`, `t`.`MoneyCost`, `t`.`ReqSkillLine`, `t`.`ReqSkillRank`, `m`.`old_id`, `t`.`ReqAbility2`, `t`.`ReqAbility3`, 81, 0 FROM `dc_tmp_class_item_map` AS `m` JOIN `trainer_spell` AS `t` ON `t`.`SpellId` = `m`.`old_id` WHERE `m`.`new_id` IN (920009, 920010);

-- Poison enchantments: the proc rate of the level-80 enchantment, if it has one
DELETE FROM `spell_enchant_proc_data` WHERE `entry` IN (922101, 922102, 922103, 922104, 922111, 922112, 922113, 922114, 922121, 922122, 922123, 922124, 922131, 922132, 922133, 922134);
INSERT INTO `spell_enchant_proc_data` (`entry`, `customChance`, `PPMChance`, `procEx`, `attributeMask`) SELECT `e`.`new_id`, `p`.`customChance`, `p`.`PPMChance`, `p`.`procEx`, `p`.`attributeMask` FROM (SELECT 922101 AS `new_id`, 3769 AS `old_id` UNION ALL SELECT 922102, 3769 UNION ALL SELECT 922103, 3769 UNION ALL SELECT 922104, 3769 UNION ALL SELECT 922111, 3771 UNION ALL SELECT 922112, 3771 UNION ALL SELECT 922113, 3771 UNION ALL SELECT 922114, 3771 UNION ALL SELECT 922121, 3773 UNION ALL SELECT 922122, 3773 UNION ALL SELECT 922123, 3773 UNION ALL SELECT 922124, 3773 UNION ALL SELECT 922131, 3774 UNION ALL SELECT 922132, 3774 UNION ALL SELECT 922133, 3774 UNION ALL SELECT 922134, 3774) AS `e` JOIN `spell_enchant_proc_data` AS `p` ON `p`.`entry` = `e`.`old_id`;

-- Poison vendors: every vendor of a level-80 poison sells its new ranks
DELETE FROM `npc_vendor` WHERE `item` IN (423101, 423102, 423103, 423104, 423111, 423112, 423113, 423114, 423121, 423122, 423123, 423124, 423131, 423132, 423133, 423134);
INSERT INTO `npc_vendor` (`entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `VerifiedBuild`) SELECT `v`.`entry`, `v`.`slot`, `n`.`new_id`, 0, 0, 0, 0 FROM `npc_vendor` AS `v` JOIN (SELECT 423101 AS `new_id`, 43231 AS `old_id` UNION ALL SELECT 423102, 43231 UNION ALL SELECT 423103, 43231 UNION ALL SELECT 423104, 43231 UNION ALL SELECT 423111, 43233 UNION ALL SELECT 423112, 43233 UNION ALL SELECT 423113, 43233 UNION ALL SELECT 423114, 43233 UNION ALL SELECT 423121, 43235 UNION ALL SELECT 423122, 43235 UNION ALL SELECT 423123, 43235 UNION ALL SELECT 423124, 43235 UNION ALL SELECT 423131, 43237 UNION ALL SELECT 423132, 43237 UNION ALL SELECT 423133, 43237 UNION ALL SELECT 423134, 43237) AS `n` ON `n`.`old_id` = `v`.`item` WHERE `v`.`ExtendedCost` = 0;

DROP TEMPORARY TABLE `dc_tmp_class_item_map`;
